#include "exgine/gles_probe_material.hpp"
#include <algorithm>
#include <cmath>
namespace exgine {
ProbeMaterialSet select_probe_material_set(const ReflectionProbeRegistry&r,Vec3 p,std::uint32_t max)noexcept{ProbeMaterialSet s;auto v=r.blend(p,std::min<std::size_t>(4,max));float total=0;for(std::size_t i=0;i<v.size();i++){s.probes[i]=v[i];float dx=p.x-v[i]->position.x,dy=p.y-v[i]->position.y,dz=p.z-v[i]->position.z,d=std::sqrt(dx*dx+dy*dy+dz*dz);s.weights[i]=r.weight(v[i]->id)*std::max(0.f,1.f-d/std::max(.001f,v[i]->blend_distance));total+=s.weights[i];}if(total>0)for(std::size_t i=0;i<v.size();i++)s.weights[i]/=total;s.count=std::uint32_t(v.size());return s;}
const char* probe_blended_pbr_fragment_shader()noexcept{return R"GLSL(#version 310 es
precision highp float;in vec3 v_world_pos;in vec3 v_normal;in vec2 v_uv;uniform samplerCube u_environment,u_ibl_irradiance,u_ibl_specular;uniform float u_ibl_intensity,u_ibl_max_lod;uniform int u_probe_count;uniform samplerCube u_probe_irradiance0,u_probe_specular0,u_probe_irradiance1,u_probe_specular1,u_probe_irradiance2,u_probe_specular2,u_probe_irradiance3,u_probe_specular3;uniform vec4 u_probe_position_radius0,u_probe_position_radius1,u_probe_position_radius2,u_probe_position_radius3,u_probe_weight0,u_probe_weight1,u_probe_weight2,u_probe_weight3;uniform float u_roughness,u_metallic,u_specular;uniform vec3 u_base_color,u_emission;out vec4 o;float W(vec3 p,vec4 pr,vec4 ww){return ww.x*max(0.,1.-distance(p,pr.xyz)/max(pr.w,1e-4));}void main(){vec3 n=normalize(v_normal),v=normalize(-v_world_pos),r=reflect(-v,n),irr=texture(u_ibl_irradiance,n).rgb,spec=textureLod(u_ibl_specular,r,u_roughness*u_ibl_max_lod).rgb;float total=0.;if(u_probe_count>0){float w=W(v_world_pos,u_probe_position_radius0,u_probe_weight0);irr+=texture(u_probe_irradiance0,n).rgb*w;spec+=textureLod(u_probe_specular0,r,u_roughness*u_ibl_max_lod).rgb*w;total+=w;}if(u_probe_count>1){float w=W(v_world_pos,u_probe_position_radius1,u_probe_weight1);irr+=texture(u_probe_irradiance1,n).rgb*w;spec+=textureLod(u_probe_specular1,r,u_roughness*u_ibl_max_lod).rgb*w;total+=w;}if(u_probe_count>2){float w=W(v_world_pos,u_probe_position_radius2,u_probe_weight2);irr+=texture(u_probe_irradiance2,n).rgb*w;spec+=textureLod(u_probe_specular2,r,u_roughness*u_ibl_max_lod).rgb*w;total+=w;}if(u_probe_count>3){float w=W(v_world_pos,u_probe_position_radius3,u_probe_weight3);irr+=texture(u_probe_irradiance3,n).rgb*w;spec+=textureLod(u_probe_specular3,r,u_roughness*u_ibl_max_lod).rgb*w;total+=w;}float inv=1./(1.+total);irr*=inv;spec*=inv;vec3 f0=mix(vec3(.04)*u_specular,u_base_color,u_metallic),kd=(1.-f0)*(1.-u_metallic);o=vec4((irr*u_base_color*kd+spec*f0)*u_ibl_intensity+u_emission,1);})GLSL";}
}